CREATE TABLE IF NOT EXISTS public.raw_kanji_data (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    kanji TEXT NOT NULL,
    jlpt_level TEXT,
    readings JSONB,
    meanings JSONB,
    example_ja TEXT,
    example_ro TEXT,
    example_en TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

DELETE FROM public.raw_kanji_data;










